class SequenceReverser:
    def __init__(self):
        self.sequence = []

    def append(self, value):
        self.sequence.append(value)

    def reverse(self):
        self.sequence.reverse()

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    values = list(map(int, data[1:]))

    reverser = SequenceReverser()
    for value in values:
        reverser.append(value)
        reverser.reverse()

    result = ' '.join(map(str, reverser.sequence))
    print(result)

if __name__ == "__main__":
    main()
